using System.Globalization;
using System.Text;
namespace SafetyMonitor;
internal sealed partial class MainForm
{
    void RefreshUi(){double pL,pR,rL,rR,hL,hR,lo,mi,hi,spl,leq;long cL,cR;lock(gate){pL=peakL;pR=peakR;rL=rmsL;rR=rmsR;hL=holdL;hR=holdR;lo=low;mi=mid;hi=high;spl=splNow;leq=leqSeconds>0?10*Math.Log10(leqEnergy/leqSeconds):double.NaN;cL=clipsL;cR=clipsR;}if((DateTime.UtcNow-holdTimeL).TotalSeconds>5)holdL=Math.Max(pL,holdL-1);if((DateTime.UtcNow-holdTimeR).TotalSeconds>5)holdR=Math.Max(pR,holdR-1);
        lPeakL.Text=$"{pL:F1}";lPeakR.Text=$"{pR:F1}";lRmsL.Text=$"{rL:F1} dBFS";lRmsR.Text=$"{rR:F1} dBFS";lHoldL.Text=$"{hL:F1} dBFS";lHoldR.Text=$"{hR:F1} dBFS";lCrestL.Text=$"{Math.Max(0,pL-rL):F1} dB";lCrestR.Text=$"{Math.Max(0,pR-rR):F1} dB";lSpl.Text=double.IsNaN(spl)?"NOT CALIBRATED":$"{spl:F1} dB SPL";lLeq.Text=double.IsNaN(leq)?"--":$"{leq:F1} dB Leq";lBands.Text=$"LOW {lo:F1}  MID {mi:F1}  HIGH {hi:F1}\n(relative dBFS)";lInfo.Text=$"Clipping L/R: {cL}/{cR} | dBFS digitale; SPL solo con microfono calibrato";
        string? alarm=null;Color col=Color.LimeGreen;if(pL>=(double)critPeak.Value||pR>=(double)critPeak.Value){alarm="CRITICAL PEAK";col=Color.Red;}else if(pL>=(double)warnPeak.Value||pR>=(double)warnPeak.Value){alarm="WARNING PEAK";col=Color.Orange;}if(!double.IsNaN(spl)){if(spl>=(double)critSpl.Value){alarm="CRITICAL SPL";col=Color.Red;}else if(spl>=(double)warnSpl.Value&&alarm==null){alarm="WARNING SPL";col=Color.Orange;}}SetStatus(alarm??"SAFE",col);if(alarm!=lastAlarm){if(alarm!=null){AddLog($"{alarm} | Peak {Math.Max(pL,pR):F1} dBFS"+(double.IsNaN(spl)?"":$" | SPL {spl:F1} dB"));if(soundBox.Checked)System.Media.SystemSounds.Exclamation.Play();}lastAlarm=alarm;}
        if(eventActive)eventRows.Add(string.Join(',',DateTime.UtcNow.ToString("O"),pL.ToString("F2",CultureInfo.InvariantCulture),pR.ToString("F2",CultureInfo.InvariantCulture),rL.ToString("F2",CultureInfo.InvariantCulture),rR.ToString("F2",CultureInfo.InvariantCulture),double.IsNaN(spl)?"":spl.ToString("F2",CultureInfo.InvariantCulture),double.IsNaN(leq)?"":leq.ToString("F2",CultureInfo.InvariantCulture),cL,cR));}
    void ToggleEvent(){if(!eventActive){eventActive=true;eventStart=DateTime.Now;eventRows.Clear();eventRows.Add("timestamp_utc,peak_l_dbfs,peak_r_dbfs,rms_l_dbfs,rms_r_dbfs,spl_db,leq_db,clip_l,clip_r");eventBtn.Text="STOP EVENTO";AddLog("EVENT START");}else{eventActive=false;eventBtn.Text="START EVENTO";var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"Safety Monitor","Events");Directory.CreateDirectory(dir);var path=Path.Combine(dir,$"Event_{eventStart:yyyyMMdd_HHmmss}.csv");File.WriteAllLines(path,eventRows,Encoding.UTF8);AddLog("EVENT SAVED: "+path);MessageBox.Show("Evento salvato:\n"+path);}}
    void SetStatus(string s,Color c){lStatus.Text=s;lStatus.ForeColor=c;}void AddLog(string s){if(InvokeRequired){BeginInvoke(()=>AddLog(s));return;}log.Items.Insert(0,$"{DateTime.Now:HH:mm:ss.fff}  {s}");while(log.Items.Count>500)log.Items.RemoveAt(log.Items.Count-1);}
}
